package com.novabank.risk.service;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import com.novabank.shared.events.BankingEvent;import io.micrometer.core.instrument.MeterRegistry;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.sql.ResultSet;import java.time.Instant;import java.util.*;import java.util.concurrent.TimeUnit;
@Component public class RiskOutboxPublisher {private final JdbcTemplate jdbc;private final KafkaTemplate<String,BankingEvent> kafka;private final ObjectMapper json;private final MeterRegistry metrics;public RiskOutboxPublisher(JdbcTemplate j,KafkaTemplate<String,BankingEvent> k,ObjectMapper o,MeterRegistry m){jdbc=j;kafka=k;json=o;metrics=m;}
 @Scheduled(fixedDelayString="${RISK_OUTBOX_PUBLISH_DELAY_MS:5000}") @Transactional public void publish(){var events=jdbc.query("select * from risk_outbox where status in ('PENDING','FAILED') and attempts<10 order by created_at for update skip locked limit 25",this::map);for(var e:events)try{Map<String,Object> payload=json.readValue(e.payload(),new TypeReference<>(){});var event=new BankingEvent(e.id(),e.type(),1,e.created(),e.correlation().toString(),null,e.aggregate(),payload);kafka.send(e.type(),e.aggregate().toString(),event).get(10,TimeUnit.SECONDS);jdbc.update("update risk_outbox set status='PUBLISHED',published_at=now() where id=?",e.id());}catch(Exception x){jdbc.update("update risk_outbox set status=case when attempts+1>=10 then 'DEAD_LETTER' else 'FAILED' end,attempts=attempts+1 where id=?",e.id());metrics.counter("novabank_kafka_retry_events_total","service","risk-service").increment();if(e.attempts()+1>=10)metrics.counter("novabank_kafka_dead_letter_events_total","service","risk-service").increment();}}private Row map(ResultSet r,int n)throws java.sql.SQLException{return new Row(r.getObject("id",UUID.class),r.getString("event_type"),r.getObject("aggregate_id",UUID.class),r.getString("payload"),r.getObject("correlation_id",UUID.class),r.getInt("attempts"),r.getTimestamp("created_at").toInstant());}private record Row(UUID id,String type,UUID aggregate,String payload,UUID correlation,int attempts,Instant created){}
}
